carregarResumo(clienteId: string): void {
  forkJoin({
    cliente: this.clienteService.obterPorId(clienteId),
    documentos: this.documentoService.listarPorCliente(clienteId)
  }).pipe(
    takeUntilDestroyed(this.destroyRef)
  ).subscribe(({ cliente, documentos }) => {
    this.nomeExibicao = cliente?.nomeSocial ?? cliente?.nome ?? 'Cliente sem nome';
    this.totalPendentes = documentos.filter(d => d.status === 'Pendente').length;
    this.ultimoEnvio = documentos.at(-1)?.dataEnvio ?? null;
  });
}

