export class ListaDocumentosComponent implements OnInit {
  documentos: Documento[] = [];

  constructor(
    private documentoService: DocumentoService,
    private notificacaoService: NotificacaoService
  ) {}

  ngOnInit(): void {
    this.carregar();

    // documentoAtualizado$ é um Subject do serviço (vive enquanto o app estiver aberto)
    this.documentoService.documentoAtualizado$.subscribe(() => {
      this.notificacaoService.mostrar('Documento atualizado');
      this.carregar();
    });
  }

  carregar(): void {
    this.documentoService.listar().subscribe(lista => this.documentos = lista);
  }
}

public async Task<ResultadoOperacao> EnviarDocumento(EnviarDocumentoDto dto)
{
    if (dto != null && dto.Arquivo != null && dto.Arquivo.Length > 0)
    {
        if (dto.Arquivo.Length <= 20 * 1024 * 1024)
        {
            var cliente = await _clienteRepository.GetById(dto.ClienteId);
            if (cliente != null)
            {
                var caminho = $"clientes/{cliente.Id}/{Guid.NewGuid()}_{dto.Arquivo.FileName}";
                await _storage.UploadAsync(caminho, dto.Arquivo.OpenReadStream());
                var documento = new Documento { ClienteId = cliente.Id, Nome = dto.Arquivo.FileName, Caminho = caminho, Status = "Pendente", DataEnvio = DateTime.UtcNow };
                await _documentoRepository.Insert(documento);
                await _emailService.Enviar(cliente.Email, "Novo documento", $"Recebemos {documento.Nome}");
                return ResultadoOperacao.Ok();
            }
            return ResultadoOperacao.Erro("Cliente não encontrado");
        }
        return ResultadoOperacao.Erro("Arquivo maior que 20 MB");
    }
    return ResultadoOperacao.Erro("Arquivo obrigatório");
}

